package org.sleepwell.app;

import android.content.*;
import android.media.AudioAttributes;
import android.os.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;

/** Explicit per-night elapsed timer. Neither settings, recovery nor a database row can admit vibration. */
final class DreamCues {
    static final long PULSE_MILLIS=120,MASK_MILLIS=PULSE_MILLIS+2000,LATE_MILLIS=30000;
    private static final Handler main=new Handler(Looper.getMainLooper());
    private static final ThreadPoolExecutor io=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(64));
    private static volatile Run current;private static volatile long maskFrom=Long.MAX_VALUE,maskTo;
    static final class Manual {final long session,start,now,active,elapsed;final String token;Manual(TrackingService.Snapshot s,TravelCues.Manual m){session=s.id;start=s.start;now=s.now;active=s.active;elapsed=SystemClock.elapsedRealtime();token=m.token;}}
    static final class State {final String nonce,phase,message;final long session,nextActive;final int requested,failed,skipped;final boolean busy;State(Run r){nonce=r.nonce;phase=r.phase;message=r.message;session=r.manual.session;nextActive=r.ordinal<r.plan.count?r.plan.due(r.ordinal):-1;requested=r.requested;failed=r.failed;skipped=r.skipped;busy=r.busy;}}
    static Manual manual(){if(TrackingService.storeFactory!=TrackingService.PRODUCTION_STORE||Records.factory!=Records.PRODUCTION)return null;TravelCues.Manual owner=TrackingService.travelManual();TrackingService.Snapshot s=TrackingService.snapshot();return owner!=null&&s!=null&&s.id==owner.session&&s.id>0&&s.phase.equals("ACTIVE")&&!s.automatic?new Manual(s,owner):null;}
    static State state(){Run r=current;return r==null?null:new State(r);}
    static Set<String> liveNonces(){Run r=current;return r!=null&&r.busy?Set.of(r.nonce):Set.of();}
    static boolean masks(long fromNanos,long toNanos){return toNanos>fromNanos&&fromNanos<maskTo&&toNanos>maskFrom;}
    static String support(Context context){try{Vibrator device=context.getSystemService(Vibrator.class);return device==null||!device.hasVibrator()?"This phone has no vibration output.":!device.hasAmplitudeControl()?"Low-amplitude vibration is unavailable on this phone.":"";}catch(RuntimeException unavailable){return "Vibration support could not be read.";}}
    static void arm(Context context,Manual expected,long revision){assertMain();Manual now=manual();if(expected==null||now==null||now.session!=expected.session||now.start!=expected.start||!now.token.equals(expected.token))throw new IllegalStateException("Use the current active manual recording to arm tonight’s cues.");if(AlarmService.active||Prefs.flag(context,"ringing"))throw new IllegalStateException("An alarm is active. Dream cues cannot be armed.");Run old=current;if(old!=null&&old.busy)throw new IllegalStateException("Dream cues are already armed. Stop them first.");DreamCueSettings plan=DreamCueSettings.load(context);if(!plan.enabled||plan.revision!=revision)throw new IllegalStateException("Save the enabled cue schedule before arming.");String unavailable=support(context);if(!unavailable.isEmpty())throw new IllegalStateException(unavailable);if(now.active>plan.due(plan.count-1)+LATE_MILLIS)throw new IllegalStateException("Tonight’s scheduled cue times have passed. No missed cues will replay.");Run next=new Run(context.getApplicationContext(),now,plan);current=next;next.begin();}
    static void cancel(String nonce){assertMain();Run run=current;if(run!=null&&run.nonce.equals(nonce))run.finish("CANCELLED","cancelled","You stopped tonight’s cues.");}
    static void cancelRun(long session,String token,String reason){assertMain();Run run=current;if(run==null||!run.busy||run.manual.session!=session||!run.manual.token.equals(token))return;String issue=reason==null?"ended":reason.toLowerCase(Locale.ROOT);if(!DreamCueTables.ISSUES.contains(issue))issue="ended";run.finish(issue.equals("process")?"INTERRUPTED":"CANCELLED",issue,issue.equals("paused")?"Tracking paused. Remaining dream cues were cancelled.":"The recording ended. Dream cues stopped.");}
    static void alarmStarting(){assertMain();Run run=current;if(run!=null&&run.busy)run.finish("CANCELLED","alarm","An alarm took priority. Remaining dream cues were cancelled.");}
    static void settingsChanged(){assertMain();Run run=current;if(run!=null&&run.busy)run.finish("CANCELLED","settings","Cue settings changed. Tonight’s remaining cues were cancelled.");}
    static void read(Context context,long session,Consumer<List<JSONObject>> complete,Consumer<String> error){Context app=context.getApplicationContext();Records.Factory factory=Records.factory;Set<String> live=liveNonces();submit(()->{try(Store store=factory.open(app)){DreamCueTables.recover(store,live);List<JSONObject> rows=session>0?store.rows("SELECT * FROM dream_cue_runs WHERE session=? ORDER BY created DESC",""+session):store.rows("SELECT r.* FROM dream_cue_runs r JOIN sessions s ON s.id=r.session ORDER BY r.created DESC LIMIT 100");for(JSONObject row:rows)row.put("requests",new JSONArray(store.rows("SELECT * FROM dream_cue_requests WHERE nonce=? ORDER BY ordinal",row.getString("nonce"))));main.post(()->complete.accept(rows));}catch(Exception failure){main.post(()->error.accept("Timed-cue history could not be read. Existing records were kept."));}},()->error.accept("Timed-cue storage is busy. Try again."));}
    private static void submit(Runnable task,Runnable rejected){try{io.execute(task);}catch(RejectedExecutionException full){main.post(rejected);}}
    private static void assertMain(){if(Looper.myLooper()!=Looper.getMainLooper())throw new IllegalStateException("Open timed dream cues to change tonight’s schedule.");}
    private static final class Run {
        final Context app;final Manual manual;final DreamCueSettings plan;final String nonce=UUID.randomUUID().toString(),localOwner=UUID.randomUUID().toString();private String terminalIssue="",phase="SAVING",message="Saving tonight’s cue schedule…";private volatile boolean busy=true;private boolean armed,pending;private int ordinal,requested,failed,skipped;private long pulseEnd;private Vibrator vibrator;
        Run(Context app,Manual manual,DreamCueSettings plan){this.app=app;this.manual=manual;this.plan=plan;}
        private boolean owns(){Manual actual=manual();return current==this&&busy&&actual!=null&&actual.session==manual.session&&actual.start==manual.start&&actual.token.equals(manual.token)&&!AlarmService.active&&!Prefs.flag(app,"ringing");}
        void begin(){submit(()->{try{JSONObject row=new JSONObject().put("nonce",nonce).put("session",manual.session).put("record_start",manual.start).put("created",manual.now).put("armed_active",manual.active).put("initial_ms",plan.first()).put("interval_ms",plan.interval()).put("cue_count",plan.count).put("revision",plan.revision).put("state","ARMED").put("finished",JSONObject.NULL).put("issue","");try(Store store=new Store(app)){DreamCueTables.arm(store,row,localOwner);}main.post(()->{armed=true;if(!busy){persistFinished(phase,terminalIssue);return;}if(!owns()){finish("INTERRUPTED","owner","The active manual recording changed. No cues were started.");return;}phase="ARMED";message="Timed cues armed for this manual night. No REM detection is used.";tick.run();});}catch(Exception problem){main.post(()->{busy=false;phase="ERROR";message=problem.getMessage()==null?"Tonight’s cue journal could not be saved.":problem.getMessage();});}},()->finish("ERROR","storage","Timed-cue storage is busy. No cue was armed."));}
        final Runnable tick=new Runnable(){@Override public void run(){if(!busy||!armed)return;if(!owns()){finish("INTERRUPTED","owner","The active manual recording is unavailable. Remaining cues stopped.");return;}try{DreamCueSettings saved=DreamCueSettings.load(app);if(!saved.enabled||saved.revision!=plan.revision){finish("CANCELLED","settings","Settings changed. Remaining cues stopped.");return;}}catch(RuntimeException unreadable){finish("ERROR","settings","Cue settings are unavailable. Remaining cues stopped.");return;}if(ordinal>=plan.count&&!pending){finish("FINISHED","","Tonight’s timed-cue schedule finished. Requests are not proof of physical delivery.");return;}Manual now=manual();if(now==null){finish("INTERRUPTED","owner","The active manual recording changed. Remaining cues stopped.");return;}if(ordinal>=plan.count){main.postDelayed(this,1000);return;}long due=plan.due(ordinal);if(!pending&&now.active>=due)claim(now,ordinal,now.active-due>LATE_MILLIS?"late":"");main.postDelayed(this,1000);}};
        void claim(Manual at,int selected,String skippedIssue){pending=true;submit(()->{try{boolean accepted;try(Store store=new Store(app)){accepted=DreamCueTables.claim(store,nonce,localOwner,selected,at.active,at.now,skippedIssue);}main.post(()->{if(!accepted){pending=false;finish("ERROR","owner","This cue was already claimed or the recording changed. Nothing was replayed.");return;}if(!skippedIssue.isEmpty()){skipped++;ordinal=selected+1;pending=false;return;}request(selected);});}catch(Exception problem){main.post(()->{pending=false;finish("ERROR","storage","The cue claim could not be saved. No new vibration was requested.");});}},()->{pending=false;finish("ERROR","storage","Timed-cue storage is busy. No new vibration was requested.");});}
        void request(int selected){Manual at=manual();if(!owns()||at==null){saveResult(selected,"CANCELLED","owner",null,null,null);return;}try{DreamCueSettings latest=DreamCueSettings.load(app);if(!latest.enabled||latest.revision!=plan.revision){saveResult(selected,"CANCELLED","settings",null,null,null);finish("CANCELLED","settings","Cue settings changed before the request. Remaining cues stopped.");return;}}catch(RuntimeException unreadable){saveResult(selected,"CANCELLED","settings",null,null,null);finish("ERROR","settings","Cue settings are unavailable. No vibration was requested.");return;}if(at.active-plan.due(selected)>LATE_MILLIS){skipped++;ordinal=selected+1;saveResult(selected,"SKIPPED","late",null,null,null);return;}String unavailable=support(app);if(!unavailable.isEmpty()){failed++;ordinal=selected+1;saveResult(selected,"FAILED","unsupported",null,null,null);pending=false;finish("ERROR","unsupported",unavailable);return;}long from=SystemClock.elapsedRealtimeNanos(),to=from+MASK_MILLIS*1000000L;maskFrom=from;maskTo=to;pulseEnd=from+PULSE_MILLIS*1000000L;Long requestedAt=null;String result="REQUESTED",issue="";try{vibrator=app.getSystemService(Vibrator.class);vibrator.vibrate(VibrationEffect.createOneShot(PULSE_MILLIS,32),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());requestedAt=at.now;requested++;message="Low vibration requested. Physical delivery is not measured.";}catch(RuntimeException failure){failed++;result="FAILED";issue="output";message="The vibration request failed. Its physical outcome is unknown.";}ordinal=selected+1;saveResult(selected,result,issue,requestedAt,at.now,at.now+MASK_MILLIS);if(!issue.isEmpty())finish("ERROR",issue,message);}
        void saveResult(int selected,String result,String issue,Long requestedAt,Long start,Long end){submit(()->{try(Store store=new Store(app)){DreamCueTables.result(store,nonce,localOwner,selected,result,issue,requestedAt,start,end);main.post(()->pending=false);}catch(Exception problem){main.post(()->storageFailure("A request receipt could not be saved. Its outcome remains uncertain; no further cues will be requested."));}},()->storageFailure("A request receipt could not be queued. Its outcome remains uncertain; no further cues will be requested."));}
        void storageFailure(String explanation){pending=false;if(busy)finish("ERROR","storage",explanation);else{phase="ERROR";terminalIssue="storage";message=explanation;if(armed)persistFinished("ERROR","storage");}}
        void finish(String terminal,String issue,String explanation){if(!busy)return;busy=false;terminalIssue=issue;phase=terminal;message=explanation;main.removeCallbacks(tick);if(vibrator!=null&&SystemClock.elapsedRealtimeNanos()<pulseEnd&&!AlarmService.active&&!Prefs.flag(app,"ringing"))try{vibrator.cancel();}catch(RuntimeException ignored){}vibrator=null;if(armed)persistFinished(terminal,issue);}
        void persistFinished(String terminal,String issue){long at=manual.now+Math.max(0,SystemClock.elapsedRealtime()-manual.elapsed);submit(()->{try(Store store=new Store(app)){DreamCueTables.finish(store,nonce,localOwner,terminal,issue,at);}catch(Exception failure){main.post(()->{phase="ERROR";message="Cues stopped, but their final journal could not be saved. Old pending claims will not replay.";});}},()->{phase="ERROR";message="Cues stopped; their final journal is pending storage.";});}
    }
    private DreamCues(){}
}
